  'acta-junta-socios-ordinaria': [
    { num:1, titulo:'Enviar convocatoria con 15 días hábiles de anticipación', descripcion:'La convocatoria debe enviarse por escrito a la dirección registrada de cada socio con al menos quince días hábiles de anticipación para las reuniones ordinarias.' },
    { num:2, titulo:'Asentar el acta en el libro oficial', descripcion:'El acta debe registrarse en el libro de actas de junta de socios debidamente registrado en la Cámara de Comercio.' },
    { num:3, titulo:'Conservar el libro de actas', descripcion:'El libro de actas es un documento legal obligatorio. Consérvelo en la sede social y preséntelo cuando lo requiera la Superintendencia de Sociedades o la Cámara de Comercio.' },
  ],
  'acta-junta-socios-cesion-cuotas': [
    { num:1, titulo:'PASO 1 de 4 — Este documento inicia el proceso de cesion de cuotas', descripcion:'Este es el primer paso obligatorio. Sin esta acta aprobada por la junta de socios no puede continuar ningun otro paso del proceso. Los 4 pasos son: PASO 1 — Acta de Junta de Socios — Aprobacion de Cesion de Cuotas (este documento). PASO 2 — Extracto de Asamblea para Reforma de Estatutos + Autorizacion de Reforma Estatutaria ante Supersociedades (solo si la sociedad esta vigilada). PASO 3 — Escritura de Reforma — Cesion de Cuotas (Ltda.) ante Notario. PASO 4 — Certificacion de Legalidad del Proceso de Cesion de Cuotas ante la Camara de Comercio.' },
    { num:2, titulo:'Verificar el derecho de preferencia ANTES de la reunion', descripcion:'Antes de convocar la junta, el gerente debe haber ofrecido las cuotas a los demas socios por escrito con 15 dias habiles de anticipacion. Guarde siempre la constancia escrita de esa oferta y la respuesta de cada socio. Sin este paso previo el proceso de cesion puede ser impugnable.' },
    { num:3, titulo:'Asentar el acta en el libro oficial de actas', descripcion:'Esta acta debe quedar registrada en el libro de actas de junta de socios debidamente inscrito en la Camara de Comercio. Es el soporte principal de todo el proceso y sin ella no puede otorgarse la escritura de reforma.' },
    { num:4, titulo:'Que sigue despues de esta acta — PASO 2', descripcion:'Despues de aprobada esta acta, saque un extracto firmado por el secretario. Si la sociedad esta vigilada por Supersociedades: use ese extracto junto con la minuta Autorizacion de Reforma Estatutaria ante Supersociedades y envie ambos documentos juntos. Si la sociedad NO esta vigilada: vaya directamente al PASO 3, la Escritura de Reforma — Cesion de Cuotas (Ltda.) ante Notario.' },
  ],
  'autorizacion-reforma-estatutaria-supersociedades': [
    { num:1, titulo:'PASO 2 de 4 — Esta carta acompana al Extracto de Asamblea', descripcion:'Esta carta NO va sola. Va siempre acompanada de la minuta "Extracto de Asamblea para Reforma de Estatutos". Ambos documentos se envian juntos en el mismo sobre a la Superintendencia de Sociedades. Este paso solo aplica si la sociedad esta vigilada por Supersociedades. Si NO esta vigilada, salte directamente al PASO 3.' },
    { num:2, titulo:'Tres documentos van juntos en el sobre a Supersociedades', descripcion:'En el mismo sobre debe incluir: 1) Esta carta de autorizacion firmada por el representante legal. 2) El extracto autentico del Acta de Junta (use la minuta "Extracto de Asamblea para Reforma de Estatutos") firmado y certificado por el secretario. 3) El certificado de existencia y representacion legal vigente de la Camara de Comercio (maximo 30 dias de expedicion).' },
    { num:3, titulo:'Esperar la autorizacion antes de ir al notario', descripcion:'Solo despues de recibir la autorizacion escrita de la Superintendencia de Sociedades puede ir al notario a otorgar la escritura de reforma. No vaya al notario sin este permiso si su sociedad esta vigilada.' },
    { num:4, titulo:'Que sigue despues — PASO 3', descripcion:'Con la autorizacion de Supersociedades en mano, use la minuta "Escritura de Reforma — Cesion de Cuotas (Ltda.)" para el PASO 3. El notario protocolizara el acta, la autorizacion de Supersociedades y la escritura en un solo instrumento publico.' },
  ],
  'escritura-reforma-cesion-cuotas-ltda': [
    { num:1, titulo:'PASO 3 de 4 — Tres personas OBLIGATORIAS ante el notario', descripcion:'A la notaria deben ir con cedulas originales: 1) El representante legal de la sociedad. 2) El cedente (quien vende sus cuotas). 3) El cesionario (quien recibe las cuotas). Sin la firma de los tres la escritura no es valida. Si viene de Supersociedades, traiga tambien la autorizacion recibida.' },
    { num:2, titulo:'Documentos que debe llevar a la notaria', descripcion:'Lleve: 1) El Acta de Junta de Socios — Aprobacion de Cesion de Cuotas (PASO 1) para que el notario la protocolice junto con la escritura. 2) Si aplica: la autorizacion de Supersociedades (PASO 2). 3) El certificado de existencia y representacion legal vigente de la Camara de Comercio.' },
    { num:3, titulo:'Que sigue despues de la escritura — PASO 4', descripcion:'Despues de otorgada la escritura vaya a la Camara de Comercio con DOS documentos juntos: 1) La escritura de reforma otorgada ante el notario. 2) La Certificacion de Legalidad del Proceso de Cesion de Cuotas (use esa minuta para generarla). Sin ambos documentos la Camara no puede registrar el cambio de socios.' },
    { num:4, titulo:'El proceso queda completo con el registro en Camara de Comercio', descripcion:'Una vez la Camara de Comercio registre la escritura y la certificacion de legalidad, el nuevo socio queda inscrito oficialmente. Solicite el nuevo certificado de existencia y representacion legal para confirmar el cambio.' },
  ],
  'certificacion-legalidad-cesion-cuotas': [
    { num:1, titulo:'PASO 4 de 4 — Este documento acompana a la Escritura de Reforma ante la Camara', descripcion:'Este certificado NO va solo. Siempre va acompanado de la Escritura de Reforma — Cesion de Cuotas (Ltda.) (PASO 3). Ambos documentos se presentan juntos en la Camara de Comercio para registrar el cambio de socios. Sin este certificado la Camara de Comercio no puede inscribir la cesion.' },
    { num:2, titulo:'Quien firma este certificado', descripcion:'Lo firma el representante legal de la sociedad (el gerente). Certifica que todo el proceso de cesion se hizo cumpliendo los articulos 363, 364 y 365 del Codigo de Comercio: que se ofrecieron las cuotas a los demas socios, que se respeto el derecho de preferencia y que se siguieron todos los pasos legales.' },
    { num:3, titulo:'Dos documentos juntos a la Camara de Comercio', descripcion:'Presente en la Camara de Comercio: 1) La Escritura de Reforma — Cesion de Cuotas (Ltda.) otorgada ante notario (PASO 3). 2) Este certificado de legalidad firmado por el representante legal. La Camara verificara ambos documentos antes de inscribir el cambio.' },
    { num:4, titulo:'Proceso completamente terminado', descripcion:'Con el registro en la Camara de Comercio el nuevo socio queda inscrito oficialmente. El proceso de cesion de cuotas produce efectos frente a la sociedad y frente a terceros desde la fecha de inscripcion. Solicite el nuevo certificado de existencia y representacion legal para confirmar.' },
  ],
