  'contrato-termino-fijo-1-3': [
    { num:1, titulo:'Firmar el contrato en dos ejemplares', descripcion:'El empleador y el trabajador deben firmar el contrato en dos (2) ejemplares originales, uno para cada parte. Se recomienda autenticar las firmas ante notario.' },
    { num:2, titulo:'Afiliar al trabajador al Sistema de Seguridad Social', descripcion:'Afiliar al trabajador a EPS, fondo de pensiones y ARP desde el primer día de trabajo y realizar los aportes correspondientes.' },
    { num:3, titulo:'Avisar con 30 días de anticipación si no va a prorrogar', descripcion:'Si alguna de las partes no quiere renovar el contrato al vencimiento, debe avisar por escrito con no menos de treinta (30) días de anticipación. Sin ese aviso el contrato se renueva automáticamente por el mismo período.' },
    { num:4, titulo:'Pagar indemnización si termina antes del vencimiento sin justa causa', descripcion:'Si el empleador termina el contrato antes del vencimiento sin justa causa, debe pagar al trabajador los salarios del tiempo que faltare para cumplir el plazo pactado. Consulte siempre con un abogado laboral.' },
  ],
  'contrato-termino-fijo-inferior-1': [
    { num:1, titulo:'Firmar el contrato en dos ejemplares', descripcion:'El empleador y el trabajador firman en dos (2) ejemplares originales. El período de prueba pactado no puede superar la quinta parte de la duración del contrato ni exceder dos meses.' },
    { num:2, titulo:'Afiliar al trabajador al Sistema de Seguridad Social', descripcion:'Aunque sea un contrato corto, el trabajador tiene derecho a seguridad social desde el primer día. Afiliarlo a EPS, pensión y ARP es obligatorio.' },
    { num:3, titulo:'Este contrato puede prorrogarse máximo 3 veces', descripcion:'Después de la primera prórroga, el contrato puede renovarse hasta por tres (3) períodos iguales o inferiores. Después de eso, la renovación no puede ser inferior a un (1) año.' },
    { num:4, titulo:'Avisar con 30 días si no renueva', descripcion:'Para no renovar el contrato, cualquiera de las partes debe avisar por escrito con al menos treinta (30) días de anticipación al vencimiento.' },
  ],
  'contrato-obra-labor': [
    { num:1, titulo:'Especificar claramente la obra o labor', descripcion:'La descripción de la obra o labor debe ser lo más precisa posible. El contrato termina cuando la obra se termina, no por el paso del tiempo, por lo que su descripción es la clave del contrato.' },
    { num:2, titulo:'Afiliar al trabajador al Sistema de Seguridad Social', descripcion:'Afiliar al trabajador a EPS, pensión y ARP desde el primer día. El empleador debe realizar aportes durante toda la ejecución de la obra.' },
    { num:3, titulo:'Firmar acta de terminación al finalizar la obra', descripcion:'Cuando la obra concluya, suscribir un acta de terminación del contrato firmada por ambas partes, donde conste que la labor fue concluida satisfactoriamente.' },
    { num:4, titulo:'Liquidar todas las prestaciones sociales', descripcion:'Al terminar el contrato, liquidar cesantías, intereses a las cesantías, prima de servicios y vacaciones proporcionales al tiempo trabajado.' },
  ],
  'contrato-salario-integral': [
    { num:1, titulo:'El salario integral debe ser mínimo 13 SMLMV', descripcion:'El salario integral no puede ser inferior a diez (10) salarios mínimos legales mensuales más el factor prestacional que no puede ser inferior al treinta por ciento (30%). Verifique el valor actual del SMLMV.' },
    { num:2, titulo:'Liquidar prestaciones previas antes de iniciar el salario integral', descripcion:'Si el trabajador ya tenía contrato anterior, debe recibir liquidación definitiva de cesantías y demás prestaciones causadas hasta la fecha del cambio a salario integral, sin que ello implique terminación del contrato.' },
    { num:3, titulo:'El salario integral no cubre las vacaciones', descripcion:'Aunque el salario integral incluye primas, cesantías, recargos y demás, las VACACIONES no están cubiertas y deben reconocerse y pagarse por separado.' },
    { num:4, titulo:'Firmar el contrato en dos ejemplares ante testigos', descripcion:'El contrato debe firmarse en dos (2) ejemplares ante testigos. Se recomienda autenticar las firmas ante notario para mayor seguridad probatoria.' },
  ],
  'reglamento-interno-trabajo': [
    { num:1, titulo:'Presentarlo al Ministerio del Trabajo para aprobación', descripcion:'El reglamento debe presentarse ante la Inspección de Trabajo correspondiente en tres (3) ejemplares, junto con el certificado de existencia y representación legal de la empresa.' },
    { num:2, titulo:'Publicarlo en la empresa dentro de los 15 días siguientes', descripcion:'Una vez aprobado, el empleador debe publicarlo en el lugar de trabajo mediante la fijación de dos (2) copias en caracteres legibles en dos (2) sitios distintos y visibles.' },
    { num:3, titulo:'Entra en vigencia 8 días después de su publicación', descripcion:'El reglamento no entra en vigor el mismo día de su publicación sino ocho (8) días después. Cuente correctamente el término para saber desde cuándo obliga a trabajadores y empleador.' },
    { num:4, titulo:'Está obligado si tiene más de 5 trabajadores permanentes', descripcion:'Toda empresa comercial con más de cinco (5) trabajadores permanentes debe tener reglamento interno de trabajo. Las empresas industriales con más de diez (10) y las agrícolas con más de veinte (20).' },
  ],

